from openpyxl import load_workbook
import sys

wb = load_workbook('sales_data.xlsx')
ws = wb.active

# Read header row to find relevant columns
headers = {}
for cell in ws[1]:
    if cell.value is not None:
        headers[cell.column] = str(cell.value).strip().lower()

print('Headers found:')
for col, name in sorted(headers.items()):
    print(f'  Col {col} ({cell_name(col)}): {name}')

# Locate profit and revenue/sales columns
profit_col = None
revenue_col = None
for col, name in headers.items():
    if 'profit' in name and profit_col is None:
        profit_col = col
    if ('revenue' in name or 'sales' in name) and revenue_col is None:
        revenue_col = col

print(f'Profit column: {profit_col}, Revenue/Sales column: {revenue_col}')
